from flask import Flask, request
import sqlite3, os, subprocess

app = Flask(__name__)
DB = sqlite3.connect('users.db')  # module-level connection

@app.route('/user')
def get_user():
    name = request.args.get('name')
    rows = DB.execute(f"SELECT * FROM users WHERE name = '{name}'").fetchall()
    return str(rows)

@app.route('/run', methods=['POST'])
def run_command():
    cmd = request.json.get('cmd')
    out = subprocess.check_output(cmd, shell=True)
    return out

@app.route('/file')
def read_file():
    path = request.args.get('path', '.')
    return open(os.path.join('/var/data', path)).read()

@app.route('/user', methods=['POST'])
def create_user():
    data = request.json
    DB.execute(f"INSERT INTO users VALUES ('{data['name']}', '{data['password']}')"
    DB.commit()
    return 'ok'
